#!/bin/bash
# launch of p2-c-pa-lt_b1 on 2 lane(s): one queue per lane, 1 job each.  Usage: LAUNCH NODE0 [NODE1 [NODE2]]
# (default schrodinger for every lane; lane i runs on NODEi, or on the last node given).
# Run on einstein AFTER: preflight ok, a line in phase2_exploration/SLOTS.md, the approval (orchestrator launches).
# Resume after any stop: run this script again with the same nodes (complete campaigns and done jobs are skipped).
NODES=("$@"); [ ${#NODES[@]} -eq 0 ] && NODES=(schrodinger)
NODE=${NODES[0]:-${NODES[-1]}}
echo "lane 0 on $NODE; qv2run jobs there now: $(ssh -x -o BatchMode=yes $NODE "pgrep -u jdochoa -af '[q]v2run job' | wc -l")"
ssh -x -o BatchMode=yes $NODE "mkdir -p /home/scratch/jdochoa/drivers; rm -f /home/scratch/jdochoa/drivers/STOP.p2-c-pa-lt-g4a-00; if [ -e /home/scratch/jdochoa/drivers/p2-c-pa-lt_b1_2slots_lane0.pid ] && kill -0 \$(cat /home/scratch/jdochoa/drivers/p2-c-pa-lt_b1_2slots_lane0.pid) 2>/dev/null; then echo lane 0 already runs; else setsid nohup bash -c 'echo \$\$ > /home/scratch/jdochoa/drivers/p2-c-pa-lt_b1_2slots_lane0.pid; exec /home/users/jdochoa/hllhc-quirks-search/analyses/quirks_v2/phase2_exploration/src/p2x_queue.sh $NODE 1 /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-g4a-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-c0-dif-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-c0-difc-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-g4a-02.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-g4n-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-c0-dif-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-c0-ni22-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-c0-ni22-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-c0-ni30-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-c0-ni30-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-c0-ni61-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-c0-ni61-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-c0-nic-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-c0-nic-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-c0-nix-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-g4l.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-c0-lowpt.json' > /home/scratch/jdochoa/drivers/p2-c-pa-lt_b1_2slots_lane0.log 2>&1 < /dev/null & echo lane 0 started; fi"
NODE=${NODES[1]:-${NODES[-1]}}
echo "lane 1 on $NODE; qv2run jobs there now: $(ssh -x -o BatchMode=yes $NODE "pgrep -u jdochoa -af '[q]v2run job' | wc -l")"
ssh -x -o BatchMode=yes $NODE "mkdir -p /home/scratch/jdochoa/drivers; rm -f /home/scratch/jdochoa/drivers/STOP.p2-c-pa-lt-g4a-01; if [ -e /home/scratch/jdochoa/drivers/p2-c-pa-lt_b1_2slots_lane1.pid ] && kill -0 \$(cat /home/scratch/jdochoa/drivers/p2-c-pa-lt_b1_2slots_lane1.pid) 2>/dev/null; then echo lane 1 already runs; else setsid nohup bash -c 'echo \$\$ > /home/scratch/jdochoa/drivers/p2-c-pa-lt_b1_2slots_lane1.pid; exec /home/users/jdochoa/hllhc-quirks-search/analyses/quirks_v2/phase2_exploration/src/p2x_queue.sh $NODE 1 /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-g4a-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-c0-difc-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-c0-nix-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-g4n-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-g4n-02.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-hph.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-g4h.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1/p2-c-pa-lt-c0-hs.json' > /home/scratch/jdochoa/drivers/p2-c-pa-lt_b1_2slots_lane1.log 2>&1 < /dev/null & echo lane 1 started; fi"
